<?php
declare(strict_types=1); namespace App\DataGrid\Bulk; use App\Repository\UserRepository; use App\Security\Voter\UserVoter; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\SecurityBundle\Security; use Symfony\Component\Security\Core\Authorization\AuthorizationCheckerInterface; final readonly class SetUserActiveBulkAction implements BulkActionInterface {public function __construct(private EntityManagerInterface $em,private UserRepository $repo,private AuthorizationCheckerInterface $auth,private bool $active){} public function name():string{return $this->active?'activate':'deactivate';} public function execute(array $ids,Security $s):BulkActionResult{$ids=array_values(array_unique(array_map('intval',$ids)));if(!$ids||count($ids)>500)throw new \InvalidArgumentException('Invalid selection.');$users=$this->repo->createQueryBuilder('u')->andWhere('u.id IN (:ids)')->andWhere('u.deletedAt IS NULL')->setParameter('ids',$ids)->getQuery()->getResult();if(count($users)!==count($ids))throw new \InvalidArgumentException('Unknown target.');$a=$this->active?UserVoter::BULK_ACTIVATE:UserVoter::BULK_DEACTIVATE;foreach($users as $u)if(!$this->auth->isGranted($a,$u))throw new \Symfony\Component\Security\Core\Exception\AccessDeniedException();$n=$this->em->getConnection()->transactional(function()use($users){$n=0;foreach($users as $u)if($u->isActive()!==$this->active){$u->setActive($this->active);++$n;}$this->em->flush();return$n;});return new BulkActionResult($n,$this->active?'Utilisateurs activés.':'Utilisateurs désactivés.',$ids);}}
